/* Remove outbound reference links; retain the intentional Useful links section. */
(function(root){'use strict';
function outbound(a){const href=(a.getAttribute('href')||'').trim();if(!/^(?:https?:)?\/\//i.test(href)||a.closest('.useful-links'))return false;try{const url=new URL(href,'https://hvacstudio.vn/'),host=url.hostname.toLowerCase(),local=a.ownerDocument.location?.hostname?.toLowerCase();return !['hvacstudio.vn','www.hvacstudio.vn',local].includes(host);}catch{return false;}}
function strip(node){if(!node||![1,9,11].includes(node.nodeType))return;const doc=node.nodeType===9?node:node.ownerDocument,anchors=[...(node.matches?.('a[href]')?[node]:[]),...node.querySelectorAll('a[href]')],parents=new Set(),references=new Set();for(const a of anchors){if(!outbound(a))continue;const reference=a.closest('section#references');if(reference)references.add(reference);if(a.parentElement)parents.add(a.parentElement);a.remove();}for(const section of references){if(!section.querySelector('a[href]')){section.remove();doc.querySelectorAll('a[href="#references"]').forEach(a=>{const li=a.parentElement;if(li?.tagName==='LI')li.remove();else a.remove();});}}for(const p of parents){if(p.tagName==='P'&&!p.querySelector('input,select,button,svg,img,a')&&/^(?:(?:Nguồn|Sources?|References?|Tài liệu(?: tham khảo)?|Tham khảo)\s*:?\s*)?[\s·•|,;:↗→–—-]*$/iu.test(p.textContent.trim()))p.remove();}}
const api={strip,outbound};if(typeof module!=='undefined'&&module.exports)module.exports=api;if(root.document){root.HVACReferenceLinks=api;strip(root.document);const target=root.document.body||root.document.documentElement;new MutationObserver(records=>{for(const r of records)for(const n of r.addedNodes)strip(n);}).observe(target,{childList:true,subtree:true});}
})(typeof window!=='undefined'?window:globalThis);
